{#- Pre-printed pad (A5 landscape, 210 x 148 mm): only values are printed.
    If the print lands off the pad's labels, change dx / dy below (mm, + = right / down). -#}
{%- set dx = 0 -%}
{%- set dy = 0 -%}
{%- set fd = "dd/MM/yyyy" -%}
{%- set farmer = doc.farmer_name or "" -%}
{%- set village = doc.village_name or (frappe.db.get_value("Village Master", doc.village, "village_name") if doc.village else "") or doc.village or "" -%}
{%- set tractor = (frappe.db.get_value("Tractor Number", doc.vehicle, "tractor_number") if doc.vehicle else "") or doc.vehicle_no or doc.vehicle or "" -%}
{%- set cutter = (frappe.db.get_value("Contractor Master", doc.cutting_contractor, "contractor_name") if doc.cutting_contractor else "") or "" -%}
{%- set carrier = (frappe.db.get_value("Contractor Master", doc.transport_contractor, "contractor_name") if doc.transport_contractor else "") or "" -%}
{%- set agent = (frappe.db.get_value("Cane Agent", doc.agent, "agent_name") if doc.agent else "") or "" -%}
{%- set gross = doc.gross_weight or 0 -%}
{%- set tare = doc.tare_weight or 0 -%}
{%- set cane = doc.cane_weight or (gross - tare if gross and tare else 0) -%}
{%- set net = doc.net_cane_weight or 0 -%}
{%- set ded = cane - net if cane and net else 0 -%}
<script>document.title = "{{ doc.name }}";</script>
<style>
@font-face { font-family: "SlipDeva"; font-weight: normal; src: url("/assets/vyavantra_weighbridge/fonts/NotoSansDevanagari-Regular.ttf") format("truetype"); }
@font-face { font-family: "SlipDeva"; font-weight: bold; src: url("/assets/vyavantra_weighbridge/fonts/NotoSansDevanagari-Bold.ttf") format("truetype"); }
.print-format { page-size: A5; orientation: Landscape; margin-top: 0mm; margin-bottom: 0mm; margin-left: 0mm; margin-right: 0mm; padding: 0; }
@page { size: A5 landscape; margin: 0; }
.ws, .ws div { font-family: "SlipDeva", "Noto Sans Devanagari", sans-serif; color: #000; }
.ws { position: relative; width: 209mm; height: 146mm; overflow: hidden; }
.ws .in { position: absolute; left: {{ dx }}mm; top: {{ dy }}mm; width: 209mm; height: 146mm; }
.ws .a { position: absolute; white-space: nowrap; font-weight: bold; }
.ws .vl { font-size: 15px; line-height: 7mm; }
.ws .rv { font-size: 12.5px; line-height: 4.2mm; white-space: normal; }
.ws .wv { font-size: 17px; line-height: 6.6mm; text-align: right; }
</style>
<div class="ws"><div class="in">
<div class="a vl" style="left:91.8mm; top:50.1mm; width:60mm; overflow:hidden">{{ doc.name }}</div>
<div class="a vl" style="left:91.8mm; top:57.2mm; width:60mm; overflow:hidden">{{ farmer }}</div>
<div class="a vl" style="left:91.8mm; top:64.3mm; width:60mm; overflow:hidden">{{ village }}</div>
<div class="a vl" style="left:91.8mm; top:71.5mm; width:60mm; overflow:hidden">{{ cutter }}</div>
<div class="a vl" style="left:91.8mm; top:78.8mm; width:60mm; overflow:hidden">{{ carrier }}</div>
<div class="a vl" style="left:91.8mm; top:86.1mm; width:60mm; overflow:hidden">{{ agent }}</div>
<div class="a rv" style="left:181mm; top:50.5mm; width:28mm">{{ frappe.utils.formatdate(doc.slip_date, fd) }}</div>
<div class="a rv" style="left:181mm; top:57.9mm; width:28mm">{{ doc.shift or "" }}</div>
<div class="a rv" style="left:181mm; top:65.0mm; width:28mm">{{ (doc.get_formatted("slip_time") or "")[:5] if doc.slip_time else "" }}</div>
<div class="a rv" style="left:181mm; top:72.1mm; width:28mm">{{ doc.variety or "" }}{% if doc.cane_type %} ({{ doc.cane_type }}){% endif %}</div>
<div class="a rv" style="left:181mm; top:79.3mm; width:28mm">{{ tractor }}</div>
<div class="a wv" style="left:82mm; top:97.1mm; width:71.5mm">{{ "%d"|format(gross) }} किलो</div>
<div class="a wv" style="left:82mm; top:105.6mm; width:71.5mm">{{ "%d"|format(tare) }} किलो</div>
<div class="a wv" style="left:82mm; top:114.1mm; width:71.5mm">{{ "%d"|format(cane) }} किलो</div>
<div class="a wv" style="left:82mm; top:122.6mm; width:71.5mm">{{ "%d"|format(ded) }} किलो</div>
<div class="a wv" style="left:82mm; top:131.1mm; width:71.5mm">{{ "%d"|format(net) }} किलो</div>
</div></div>
